mapper.select:
SELECT FROM biz_cst C JOIN biz_info B ON B.BIZ_ID=C.BIZ_ID LEFT JOIN user_info U ON U.USER_ID=COALESCE(C.EXPNS_USER_ID,C.RGTR_ID) WHERE C.USE_YN='Y' AND COALESCE(C.EXPNS_USER_ID,C.RGTR_ID)=#{userId}
AND (B.BIZ_NM LIKE CONCAT('%',#{searchKeyword},'%') OR B.BIZ_ABRV_NM LIKE CONCAT('%',#{searchKeyword},'%') OR C.CST_NM LIKE CONCAT('%',#{searchKeyword},'%') OR C.MERCHANT_NM LIKE CONCAT('%',#{searchKeyword},'%'))
ORDER BY C.OCRN_YMD DESC,C.BIZ_CST_SN DESC

SELECT B.BIZ_ID bizId, B.BIZ_NM bizNm, B.BIZ_ABRV_NM bizAbrvNm FROM biz_info B WHERE B.CO_ID=#{coId}
AND (B.RGTR_ID=#{userId} OR EXISTS(SELECT 1 FROM biz_mnpw M WHERE M.BIZ_ID=B.BIZ_ID AND M.USER_ID=#{userId} AND M.USE_YN='Y'))
ORDER BY B.BIZ_CD,B.BIZ_NM

mapper.update:
UPDATE biz_cst C SET C.USE_YN='N',C.MDFCN_DT=NOW(),C.MDFR_ID=#{mdfrId}
WHERE C.BIZ_CST_SN=#{claimSn} AND C.USE_YN='Y'
  AND COALESCE(C.EXPNS_USER_ID,C.RGTR_ID)=#{userId}
  AND EXISTS(SELECT 1 FROM biz_info B WHERE B.BIZ_ID=C.BIZ_ID AND B.CO_ID=#{coId})
